//! Earcons: start (recording began), done (text pasted) and no-AI (pasted
//! without AI cleanup). The WAVs are generated by `scripts/generate-sounds.mjs`.
//!
//! Cues play on one background thread that keeps the output device open for a
//! short while after the last cue, so back-to-back cues (start, then done a
//! few seconds later) do not pay for reopening it. The stream is dropped when
//! idle: an open render stream keeps Windows from sleeping and pins Bluetooth
//! headsets, and reopening also follows default-device changes.

use std::io::Cursor;
use std::sync::mpsc::{self, RecvTimeoutError, Sender};
use std::sync::{Mutex, OnceLock};
use std::time::Duration;

use rodio::Source;

const START: &[u8] = include_bytes!("../sounds/start.wav");
const DONE: &[u8] = include_bytes!("../sounds/done.wav");
const NO_AI: &[u8] = include_bytes!("../sounds/no-ai.wav");

/// How long the output stays open after the last cue.
const KEEP_OPEN: Duration = Duration::from_secs(30);

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Cue {
    Start,
    Done,
    NoAi,
}

impl Cue {
    pub fn parse(name: &str) -> Option<Self> {
        match name {
            "start" => Some(Self::Start),
            "done" => Some(Self::Done),
            "no-ai" => Some(Self::NoAi),
            _ => None,
        }
    }

    fn bytes(self) -> &'static [u8] {
        match self {
            Self::Start => START,
            Self::Done => DONE,
            Self::NoAi => NO_AI,
        }
    }
}

fn player() -> &'static Mutex<Option<Sender<Cue>>> {
    static PLAYER: OnceLock<Mutex<Option<Sender<Cue>>>> = OnceLock::new();
    PLAYER.get_or_init(|| Mutex::new(None))
}

/// Queue a cue; returns immediately. Never blocks the caller on audio I/O.
pub fn play(cue: Cue) {
    let mut guard = player().lock().unwrap_or_else(|e| e.into_inner());
    if let Some(tx) = guard.as_ref() {
        if tx.send(cue).is_ok() {
            return;
        }
    }
    let (tx, rx) = mpsc::channel::<Cue>();
    let _ = tx.send(cue);
    let spawned = std::thread::Builder::new().name("chirp-sound".into()).spawn(move || {
        // rodio's OutputStream is !Send, so it lives and dies on this thread.
        let mut output: Option<(rodio::OutputStream, rodio::OutputStreamHandle)> = None;
        loop {
            match rx.recv_timeout(KEEP_OPEN) {
                Ok(cue) => {
                    if output.is_none() {
                        output = rodio::OutputStream::try_default()
                            .map_err(|e| log::warn!("Sound output unavailable: {e}"))
                            .ok();
                    }
                    let Some((_, handle)) = output.as_ref() else { continue };
                    match rodio::Decoder::new(Cursor::new(cue.bytes())) {
                        Ok(source) => {
                            if let Err(e) = handle.play_raw(source.convert_samples()) {
                                log::warn!("Sound playback failed: {e}");
                                output = None;
                            }
                        }
                        Err(e) => log::warn!("Sound decode failed: {e}"),
                    }
                }
                Err(RecvTimeoutError::Timeout) => output = None,
                Err(RecvTimeoutError::Disconnected) => break,
            }
        }
    });
    match spawned {
        Ok(_) => *guard = Some(tx),
        Err(e) => log::warn!("Sound thread failed to start: {e}"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_cue_names() {
        assert_eq!(Cue::parse("start"), Some(Cue::Start));
        assert_eq!(Cue::parse("done"), Some(Cue::Done));
        assert_eq!(Cue::parse("no-ai"), Some(Cue::NoAi));
        assert_eq!(Cue::parse("chirp"), None);
    }

    #[test]
    fn cues_are_short_decodable_wavs() {
        for cue in [Cue::Start, Cue::Done, Cue::NoAi] {
            let source = rodio::Decoder::new(Cursor::new(cue.bytes())).expect("decodes");
            let rate = source.sample_rate() as usize;
            let channels = source.channels() as usize;
            let samples = source.count();
            let ms = samples * 1000 / (rate * channels);
            assert!(ms > 0 && ms <= 90, "{cue:?} is {ms} ms");
        }
    }
}
